import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { CircleProgressProps } from "./circle-progress.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

const componentName = "CircleProgress";

export const CircleProgressClasses = {
  root: "exp-textura_circle-progress",
  determinate: "exp-textura_circle-progress_determinate",
  indeterminate: "exp-textura_circle-progress_indeterminate",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  inverse: {
    indeterminateCircle: { stroke: theme.progress.color.inverse.indicator },
    determinateCircle: { stroke: theme.progress.color.inverse.indicator },
  },
  inherit: {
    indeterminate: { width: "1em", height: "1em", display: "inline-flex" },
    determinate: { width: "1em", height: "1em", display: "inline-flex" },
    indeterminateCircle: { stroke: "currentColor" },
    determinateCircle: { stroke: "currentColor" },
  },
});

const generateStyles = (props: CircleProgressProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<CircleProgressProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "flex",
    alignItems: "center",
    width: "fit-content",

    [`& .${CircleProgressClasses.indeterminate}`]: {
      display: "inline-block",
      width: theme.toRem(48),
      height: theme.toRem(48),
      svg: {
        width: "100%",
        height: "100%",
        transformOrigin: "center",
        animation: "exp-textura-circular-progress-container-rotate 1.6s linear infinite",
      },
      circle: {
        fill: "none",
        stroke: theme.progress.color.default.indicator,
        strokeWidth: theme.toRem(theme.spacing[4]),
        strokeLinecap: "round",
        strokeDasharray: "80",
        strokeDashoffset: "60",
        animation: "exp-textura-circular-progress-dash 1.5s ease-in-out infinite",
        ...styleSlots?.indeterminateCircle,
      },
      ...styleSlots?.indeterminate,
    },

    [`& .${CircleProgressClasses.determinate}`]: {
      display: "inline-block",
      width: theme.toRem(48),
      height: theme.toRem(48),
      svg: {
        width: "100%",
        height: "100%",
        transformOrigin: "center",
      },
      circle: {
        fill: "none",
        stroke: theme.progress.color.default.indicator,
        strokeWidth: theme.toRem(theme.spacing[4]),
        strokeLinecap: "round",
        transition: "stroke-dashoffset 0.35s ease",
        ...styleSlots?.determinateCircle,
      },
      ...styleSlots?.determinate,
    },

    "@keyframes exp-textura-circular-progress-container-rotate": {
      to: { transform: "rotate(360deg)" },
    },

    "@keyframes exp-textura-circular-progress-dash": {
      "0%": {
        strokeDasharray: "1, 200",
        strokeDashoffset: "0",
      },
      "50%": {
        strokeDasharray: "100, 200",
        strokeDashoffset: "-15",
      },
      "100%": {
        strokeDasharray: "1, 200",
        strokeDashoffset: "-125",
      },
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps("progressType");

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledCircleProgress = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<CircleProgressProps>((props) => generateStyles(props));
